import hashlib,io,json,shutil,sys,tarfile,time
from pathlib import Path
from legal_skill_guard.experiment.storage import RunStore
from legal_skill_guard.learning.experiment import now,read,sha
root=Path.cwd();definition_path=Path(sys.argv[1]);definition=read(definition_path);f=definition_path.parent;launch=read(f/'actual_launch.json');worker=Path('/proc')/str(launch['pid']);out=root/'runs'/launch['run_id']
while True:
 try: state=worker.joinpath('stat').read_text().rsplit(')',1)[1].split()
 except FileNotFoundError: break
 if state[19]!=launch['process_start_ticks'] or state[0]=='Z':break
 time.sleep(15)
try:
 config=Path(definition['config']);frozen=Path(definition['frozen']);assert sha(config)==definition['config_sha256'] and sha(frozen)==definition['frozen_sha256']
 bound=read(frozen)['files'];assert all(sha(p)==h for p,h in bound.items())
 files={str(Path(p).resolve().relative_to(root)):h for p,h in bound.items()}
 for p in [config,frozen,definition_path,*(p for p in f.glob('*.json')),*(p for p in out.rglob('*') if p.is_file() and p.suffix in ('.json','.py','.md'))]:
  assert not p.is_symlink();files[str(p.relative_to(root))]=sha(p)
 progress=read(out/'progress.json');name=launch['run_id']+'-actual-terminal-recovery.tar.gz';target=root.parent/'legal-skill-backups'/name;copy=Path('/home/yndx/hhy/legal-skill-rootdisk-backups')/name
 assert not target.exists() and not copy.exists() and target.parent.stat().st_dev!=copy.parent.stat().st_dev
 meta={'at':now(),'files':files,'worker_original_terminal_verified':True,'actual_progress_state':progress['state'],'actual_complete_record_exists':(out/'completion.json').exists(),'full_Git_and_source_base_receipt':definition['full_Git_and_source_base_receipt'],'same_host_not_offsite_weights_auth_or_whole_machine':True};payload=json.dumps(meta,ensure_ascii=False,sort_keys=True).encode()
 with tarfile.open(target,'x:gz',compresslevel=2) as arc:
  for name in sorted(files):arc.add(root/name,arcname='project/'+name,recursive=False)
  info=tarfile.TarInfo('terminal_recovery_manifest.json');info.size=len(payload);arc.addfile(info,io.BytesIO(payload))
 expected={'project/'+n:h for n,h in files.items()}|{'terminal_recovery_manifest.json':hashlib.sha256(payload).hexdigest()};got={}
 with tarfile.open(target,'r|gz') as arc:
  for item in arc:
   assert item.isfile() and item.name in expected;stream=arc.extractfile(item);digest=hashlib.sha256()
   while chunk:=stream.read(1048576):digest.update(chunk)
   got[item.name]=digest.hexdigest();assert got[item.name]==expected[item.name]
 assert got==expected;shutil.copy2(target,copy);assert sha(copy)==sha(target)
 result={'at':now(),'state':'terminal_results_preserved','original_worker_terminal_verified':True,'actual_progress_state':progress['state'],'actual_complete_record_exists':(out/'completion.json').exists(),'archive':str(target),'archive_sha256':sha(target),'rootdisk_copy':str(copy),'copy_sha256':sha(copy),'all_members_verified':True,'different_filesystems_verified':True,'project_files':len(files),'members':len(expected),'no_new_native_teacher_calls':True,'same_host_not_offsite_weights_auth_or_whole_machine':True}
except BaseException as error:
 import traceback
 result={'at':now(),'state':'terminal_preservation_failed','error':repr(error),'traceback':traceback.format_exc(),'original_worker_terminal_verified':True,'no_worker_or_model_restart_or_result_change':True}
RunStore.immutable_json(f/'terminal_preservation_completion.json',result)
